insert into i18n_bundles (locale, code, value) values ('tr', 'fasting.reason-groups.voluntary.reasons[3].cites[1].intro', 'Abdullah b. Amr b. Âs (r.a.) rivayet etti:');
insert into i18n_bundles (locale, code, value) values ('tr', 'fasting.reason-groups.voluntary.reasons[3].cites[1].quote', 'Sana ayda üç gün oruç yeter. Çünkü her iyiliğin karşılığı on katıyla verilir; böylece bu, bütün yıl oruç tutmuş gibi olur.');
