insert into i18n_bundles (locale, code, value) values ('tr', 'fasting.reason-groups.voluntary.reasons[3].cites[1].references[0].hadith', '1975');
insert into i18n_bundles (locale, code, value) values ('tr', 'fasting.reason-groups.voluntary.reasons[3].cites[2].intro', 'Ebû Katâde (r.a.), Resûlullah’ın (s.a.v.) şöyle buyurduğunu rivayet etmiştir:');
insert into i18n_bundles (locale, code, value) values ('tr', 'fasting.reason-groups.voluntary.reasons[3].cites[2].quote', 'Her aydan üç gün oruç tutmak ve yılda bir Ramazan orucunu tutmak, sürekli oruç gibidir.');
