insert into i18n_bundles (locale, code, value) values ('tr', 'fasting.reason-groups.voluntary.reasons[3].cites[4].quote', 'Her aydan üç gün oruç tutmak, bütün yıl oruç tutmak gibidir. Beyaz günler: on üçüncü, on dördüncü ve on beşinci günlerdir.');
