insert into i18n_bundles (locale, code, value) values ('tr', 'fasting.reason-groups.voluntary.reasons[3].cites[5].quote', 'Yakın dostum (s.a.v.) bana üç şeyi tavsiye etti: Her aydan üç gün oruç tutmayı, iki rekât kuşluk namazı kılmayı ve uyumadan önce vitir namazı kılmayı.');
