insert into i18n_bundles (locale, code, value) values ('tr', 'fasting.reason-groups.voluntary.reasons[3].cites[6].quote', 'Dostum (s.a.v.) bana üç şeyi hiçbir zaman terk etmemem üzere tavsiye etti; bana her aydan üç gün oruç tutmayı tavsiye etti.');
insert into i18n_bundles (locale, code, value) values ('tr', 'fasting.reason-groups.voluntary.reasons[3].cites[6].references[0].collection', 'abudawud');
