insert into i18n_bundles (locale, code, value) values ('tr', 'fasting.reason-groups.voluntary.reasons[3].cites[0].quote', 'Ayın herhangi bir günlerinde oruç tutacaksan on üçüncü, on dördüncü ve on beşinci günleri tut.');
