insert into i18n_bundles (locale, code, value) values ('tr', 'fasting.reason-groups.voluntary.reasons[4].cites[1].intro', 'Üsâme b. Zeyd (r.a.), Resûlullah’ın (s.a.v.) şöyle buyurduğunu rivayet etmiştir:');
insert into i18n_bundles (locale, code, value) values ('tr', 'fasting.reason-groups.voluntary.reasons[4].cites[1].quote', 'Onlar, amellerin Âlemlerin Rabbi’ne arz edildiği iki gündür. Ben, amelim arz edilirken oruçlu olmayı severim.');
