insert into i18n_bundles (locale, code, value) values ('tr', 'fasting.reason-groups.voluntary.reasons[4].cites[2].quote', 'O, benim doğduğum gündür; peygamber olarak gönderildiğim ya da bana vahiy indirilen gündür.');
